// Generates web/auth-config.json from the INTENDED backend's private .env
// (FYP/backend/.env), not from the throwaway FYP/test server.
//
// The output contains ONLY the values that are public by design — the
// Supabase project URL and the publishable (client-safe) key. The service-role
// / secret key, JWKS URL and database credentials are server-side only and are
// never read or written here.
//
// The generated file is git-ignored; regenerate it with `npm run gen-auth-config`.
// Override the source with SITEWISE_SUPABASE_ENV when deploying.

const fs = require('fs');
const path = require('path');

const envPath = process.env.SITEWISE_SUPABASE_ENV
  ? path.resolve(process.env.SITEWISE_SUPABASE_ENV)
  : path.resolve(__dirname, '..', '..', 'backend', '.env');
const outPath = path.resolve(__dirname, '..', 'web', 'auth-config.json');

function readEnvValue(name) {
  if (!fs.existsSync(envPath)) return undefined;
  for (const line of fs.readFileSync(envPath, 'utf8').split(/\r?\n/)) {
    const match = line.match(/^([A-Z_]+)\s*=\s*(.*)$/);
    if (match && match[1] === name) {
      return match[2].replace(/^["']|["']$/g, '').trim();
    }
  }
  return undefined;
}

const supabaseUrl = (readEnvValue('SUPABASE_URL') || '').replace(/\/+$/, '');
const publishable = readEnvValue('SUPABASE_PUBLISHABLE_KEY') || '';

// Guard against accidentally publishing a secret key in a browser asset.
if (publishable.startsWith('sb_secret_') || publishable.includes('service_role')) {
  console.error('gen_auth_config: refusing to write a secret/service-role key to a public file.');
  process.exit(1);
}
if (!supabaseUrl || !publishable) {
  console.error('gen_auth_config: SUPABASE_URL / SUPABASE_PUBLISHABLE_KEY not found in', envPath);
  console.error('Configure FYP/backend/.env (see FYP/backend/.env.example).');
  process.exit(1);
}

fs.writeFileSync(outPath, JSON.stringify(
  {
    configured: true,
    supabaseUrl,
    supabasePublishableKey: publishable,
    _note: 'Generated by tool/gen_auth_config.js from FYP/backend/.env. Public client values only — never add the secret key here.',
  },
  null,
  2,
) + '\n');
console.log('gen_auth_config: wrote', outPath, '(from', envPath + ')');
